\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme: Deep navy + electric blue/teal/gold ──
\definecolor{primary}{HTML}{0F1B2D}
\definecolor{secondary}{HTML}{00B4D8}
\definecolor{accent}{HTML}{E8A838}
\definecolor{electricblue}{HTML}{2196F3}
\definecolor{tealaccent}{HTML}{00BFA5}
\definecolor{bgposter}{HTML}{0F1B2D}
\definecolor{cardbg}{HTML}{162236}
\definecolor{cardtitlebg}{HTML}{1A2A42}
\definecolor{statbg}{HTML}{0D2137}
\definecolor{textwhite}{HTML}{F0F4F8}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{textmuted}{HTML}{64748B}
\definecolor{goldhl}{HTML}{FEF3C7}
\definecolor{bluehl}{HTML}{DBEAFE}
\definecolor{tealhl}{HTML}{CCFBF1}
\definecolor{metricbg}{HTML}{1E3A5F}

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe on dark cards) ──
\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{tealaccent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{tealaccent},
    coltitle=tealaccent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={tealaccent!40},
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.3},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{electricblue},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{electricblue},
    coltitle=electricblue, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={electricblue!40},
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.3},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.3},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!15!primary,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary!80!black,
    toptitle=8pt, bottomtitle=8pt,
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.35},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ══════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  borderline south={3pt}{0pt}{secondary},
  left=40pt, right=40pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{28}{34}\selectfont\color{secondary}\textsc{Nature} \color{textgray}$\vert$ \color{textwhite}2024 \color{textgray}$\vert$ \color{textmuted}DOI: 10.1038/s41586-024-07487-w}\\[16pt]
  {\fontsize{78}{94}\selectfont\bfseries\color{white} Mapping Neural Circuit Architecture}\\[6pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{secondary} Advances in Brain Connectivity Analysis}\\[18pt]
  {\fontsize{32}{40}\selectfont\color{textgray} Large-Scale Connectomics $\vert$ Circuit Motif Discovery $\vert$ Automated Synapse Classification}
}

% ══════════════════════════════════════════
% METRICS BANNER
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=metricbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{secondary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!50}{primary!80!black}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{secondary} \raisebox{0pt}{\texttildelow}125K}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} Neurons Mapped}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{electricblue!50}{primary!80!black}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{electricblue} \raisebox{0pt}{\texttildelow}54M}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} Synaptic Connections}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{primary!80!black}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{accent} 37}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} Circuit Motifs}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{tealaccent!50}{primary!80!black}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{tealaccent} 94.2\%}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} Classification Accuracy}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════
% ROW A: Background | Methods | Key Findings (top)
% ══════════════════════════════════════════

% ── Background & Motivation ──
\posterbox[tealcard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Brain function requires circuit-level wiring maps
    \item Classical neuroanatomy lacks scale and resolution
    \item EM + ML convergence enables large-scale connectomics
  \end{itemize}
  \vspace{10pt}
  \colorbox{tealaccent!20}{\parbox{0.94\linewidth}{\centering\fontsize{30}{38}\selectfont\color{textwhite}
    \textbf{Gap:} No prior study mapped complete circuits at neuron-level resolution across entire regions
  }}
}

% ── Methodology ──
\posterbox[bluecard, title={Methodology Pipeline}
]{name=methods, column=2, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \colorbox{electricblue!15}{\parbox{0.94\linewidth}{\centering\fontsize{30}{38}\selectfont\color{textwhite}
    \textbf{Imaging} $\to$ \textbf{Segmentation} $\to$ \textbf{Detection} $\to$ \textbf{Analysis}
  }}
  \vspace{10pt}
  \begin{itemize}[itemsep=10pt]
    \item Serial-section EM at 4$\times$4$\times$30\,nm
    \item DL-based neuron tracing + human proofread
    \item CNN synapse classifier (\textbf{94.2\%} accuracy)
    \item Graph-theoretic motif detection
  \end{itemize}
  \vspace{8pt}
  \colorbox{electricblue!15}{\parbox{0.94\linewidth}{\centering\fontsize{30}{38}\selectfont\color{textwhite}
    \textbf{Validation:} Calcium imaging + optogenetic perturbation
  }}
}

% ── Key Findings (Top) ──
\posterbox[goldcard, title={Key Findings}
]{name=findings1, column=3, between=row6 and row11}{
  \fontsize{34}{44}\selectfont

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{37 connectivity motifs} --- modular wiring logic, analogous to logic gates
  }}
  \vspace{10pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{Hub neurons:} 3.5\% of cells $\Rightarrow$ 28\% of synaptic output
  }}
  \vspace{10pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{Layer 5 recurrent:} 4.7:1 ratio vs.\ feedforward
  }}
  \vspace{10pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{Inhibitory specificity:} 6.2$\times$ higher than excitatory
  }}
}

% ══════════════════════════════════════════
% ROW B: Quantitative Results | Data Table | Findings Detail
% ══════════════════════════════════════════

% ── Hub Neuron Analysis ──
\posterbox[goldcard, title={Hub Neuron Analysis}
]{name=hubs, column=1, between=row11 and row16}{
  \fontsize{34}{44}\selectfont

  \centering
  \colorbox{primary!60}{\parbox{0.94\linewidth}{\centering\vspace{8pt}
    {\fontsize{60}{72}\selectfont\bfseries\color{accent} 3.5\%}\\[4pt]
    {\fontsize{28}{34}\selectfont\color{textgray} of neurons}\\[8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite} drive \textbf{28\%} of synaptic output}
  \vspace{8pt}}}

  \vspace{12pt}
  \raggedright
  \begin{itemize}[itemsep=10pt]
    \item Non-uniform influence distribution
    \item Focal lesion $\Rightarrow$ widespread effects
    \item Implications for targeted stimulation
  \end{itemize}
}

% ── Quantitative Summary Table ──
\posterbox[bluecard, title={Quantitative Summary}
]{name=table, column=2, between=row11 and row16}{
  \fontsize{30}{38}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{p{0.48\linewidth}p{0.44\linewidth}}
    \rowcolor{electricblue!20}
    \textbf{\color{electricblue}Metric} & \textbf{\color{electricblue}Value} \\
    \rowcolor{primary!40}
    Neurons reconstructed & \textbf{\raisebox{0pt}{\texttildelow}125,000} \\
    \rowcolor{electricblue!10}
    Synapses catalogued & \textbf{\raisebox{0pt}{\texttildelow}54 million} \\
    \rowcolor{primary!40}
    Connectivity motifs & \textbf{37 types} \\
    \rowcolor{electricblue!10}
    Hub neuron fraction & \textbf{3.5\%} \\
    \rowcolor{primary!40}
    Layer 5 recurrent ratio & \textbf{4.7:1} \\
    \rowcolor{electricblue!10}
    Inhibitory specificity & \textbf{6.2$\times$} \\
    \rowcolor{primary!40}
    Synapse detection acc. & \textbf{94.2\%} \\
  \end{tabular}
}

% ── Layer-Specific Connectivity ──
\posterbox[tealcard, title={Layer-Specific Connectivity}
]{name=layers, column=3, between=row11 and row16}{
  \fontsize{34}{44}\selectfont

  \colorbox{tealaccent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{Feedforward dominant:} Layers 2/3 $\to$ Layer 4
  }}
  \vspace{10pt}

  \colorbox{tealaccent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{Recurrent enriched:} Layer 5 (4.7:1 ratio)
  }}
  \vspace{10pt}

  \colorbox{tealaccent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont\color{textwhite}
    \textbf{Inhibitory interneurons:} 6.2$\times$ more specific wiring than excitatory neurons
  }}
  \vspace{12pt}

  \begin{itemize}[itemsep=10pt]
    \item Challenges ``blanket inhibition'' model
    \item Suggests precise circuit-level computation
  \end{itemize}
}

% ══════════════════════════════════════════
% ROW C: Implications | Future Directions | References
% ══════════════════════════════════════════

% ── Implications ──
\posterbox[highlightcard, title={Implications}
]{name=implications, column=1, between=row16 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Modular motifs = finite circuit vocabulary
    \item Hub neurons explain focal lesion effects
    \item Informs brain-computer interface design
    \item Open-access dataset for community
  \end{itemize}
}

% ── Future Directions ──
\posterbox[highlightcard, title={Future Directions}
]{name=future, column=2, between=row16 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item Extend to additional brain regions
    \item Cross-species connectomic comparison
    \item Complete mammalian wiring diagram
  \end{enumerate}
  \vspace{8pt}
  \colorbox{secondary!25}{\parbox{0.94\linewidth}{\centering\fontsize{30}{38}\selectfont\color{textwhite}
    \textbf{Open Access:} Dataset \& tools publicly released
  }}
}

% ── Citation & Reference ──
\posterbox[tealcard, title={Citation}
]{name=refs, column=3, between=row16 and row20}{
  \fontsize{30}{40}\selectfont
  \textit{Nature} (2024)\\[6pt]
  DOI: 10.1038/s41586-024-07487-w\\[14pt]
  \colorbox{tealaccent!15}{\parbox{0.94\linewidth}{\fontsize{28}{36}\selectfont\color{textgray}
    Serial-section electron microscopy, deep learning segmentation, graph-theoretic circuit analysis, calcium imaging validation
  }}
  \vspace{10pt}\\
  {\fontsize{28}{34}\selectfont\color{textmuted}
  Poster prepared for academic conference presentation}
}

\end{tcbposter}
\end{document}
TEXEOF
