\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme: Deep navy + bright accents ──
\definecolor{primary}{HTML}{0F1B2D}
\definecolor{secondary}{HTML}{00B4D8}
\definecolor{accent}{HTML}{E8A838}
\definecolor{electricblue}{HTML}{2196F3}
\definecolor{tealaccent}{HTML}{00BFA5}
\definecolor{bgposter}{HTML}{0F1B2D}
\definecolor{cardbg}{HTML}{162236}
\definecolor{cardtitlebg}{HTML}{1A2A42}
\definecolor{metricbg}{HTML}{0D2137}
\definecolor{textwhite}{HTML}{F0F4F8}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{textmuted}{HTML}{64748B}
% Bright highlight backgrounds for colorboxes on dark cards
\definecolor{goldbox}{HTML}{3D2E0A}
\definecolor{tealbox}{HTML}{0A2E28}
\definecolor{bluebox}{HTML}{0A1E3D}
\definecolor{statbox}{HTML}{122D4A}

\pagecolor{bgposter}
\color{textwhite}

\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}\bfseries\arabic*.}}

\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{tealaccent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{tealaccent},
    coltitle=tealaccent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={tealaccent!40},
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.3},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{electricblue},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{electricblue},
    coltitle=electricblue, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={electricblue!40},
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.3},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.3},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!12!primary,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=secondary!70!black,
    toptitle=8pt, bottomtitle=8pt,
    colupper=textwhite,
    valign=top, drop shadow={opacity=0.35},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  borderline south={3pt}{0pt}{secondary},
  left=40pt, right=40pt, top=16pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{28}{34}\selectfont\color{secondary}\textsc{Nature} \color{textgray}$\vert$ \color{textwhite}2024 \color{textgray}$\vert$ \color{textmuted}DOI: 10.1038/s41586-024-07487-w}\\[14pt]
  {\fontsize{76}{90}\selectfont\bfseries\color{white} Mapping Neural Circuit Architecture}\\[4pt]
  {\fontsize{68}{82}\selectfont\bfseries\color{secondary} Advances in Brain Connectivity Analysis}\\[14pt]
  {\fontsize{30}{38}\selectfont\color{textgray} Large-Scale Connectomics $\vert$ Circuit Motif Discovery $\vert$ Automated Synapse Classification}
}

% ══ METRICS BANNER ══
\posterbox[
  enhanced, colback=statbox, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={2pt}{0pt}{secondary!40},
  borderline north={1pt}{0pt}{secondary!20},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{secondary!60}{primary}{\parbox{0.86\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{70}{84}\selectfont\bfseries\color{secondary} {$\sim$}125K}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textwhite} Neurons Mapped}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{electricblue!60}{primary}{\parbox{0.86\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{70}{84}\selectfont\bfseries\color{electricblue} {$\sim$}54M}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textwhite} Synaptic Connections}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{accent!60}{primary}{\parbox{0.86\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{70}{84}\selectfont\bfseries\color{accent} 37}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textwhite} Circuit Motifs}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{tealaccent!60}{primary}{\parbox{0.86\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{70}{84}\selectfont\bfseries\color{tealaccent} 94.2\%}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textwhite} Classification Acc.}\vspace{10pt}%
    }}
  \end{minipage}
}

% ══ ROW A (row5-row10): Background | Methods | Key Findings ══

\posterbox[tealcard, title={Background \& Motivation}
]{name=background, column=1, between=row5 and row10}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item Brain function requires circuit-level wiring maps
    \item Classical neuroanatomy lacks scale \& resolution
    \item EM + ML convergence enables large-scale connectomics
  \end{itemize}
  \vspace{12pt}
  \colorbox{tealbox}{\parbox{0.94\linewidth}{\vspace{6pt}\centering\fontsize{30}{38}\selectfont\color{tealaccent}
    \textbf{Key Gap:} No prior study mapped complete circuits at neuron-level resolution across entire brain regions
  \vspace{6pt}}}
}

\posterbox[bluecard, title={Methodology Pipeline}
]{name=methods, column=2, between=row5 and row10}{
  \fontsize{34}{44}\selectfont
  \colorbox{bluebox}{\parbox{0.94\linewidth}{\vspace{6pt}\centering\fontsize{32}{40}\selectfont\color{electricblue}
    \textbf{Imaging} $\to$ \textbf{Segmentation} $\to$ \textbf{Detection} $\to$ \textbf{Analysis}
  \vspace{6pt}}}
  \vspace{12pt}
  \begin{itemize}[itemsep=12pt]
    \item Serial-section EM at 4\,nm $\times$ 4\,nm $\times$ 30\,nm
    \item DL-based neuron tracing + human proofread
    \item CNN synapse classifier (\textbf{94.2\%} acc.)
    \item Graph-theoretic motif detection
  \end{itemize}
  \vspace{10pt}
  \colorbox{bluebox}{\parbox{0.94\linewidth}{\vspace{6pt}\centering\fontsize{30}{38}\selectfont\color{electricblue}
    \textbf{Validation:} Ca$^{2+}$ imaging + optogenetic perturbation
  \vspace{6pt}}}
}

\posterbox[goldcard, title={Key Findings}
]{name=findings1, column=3, between=row5 and row10}{
  \fontsize{34}{44}\selectfont

  \colorbox{goldbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{accent}
    \textbf{37 connectivity motifs} \color{textwhite}--- modular wiring logic, analogous to logic gates
  \vspace{6pt}}}
  \vspace{10pt}

  \colorbox{goldbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{accent}
    \textbf{Hub neurons:} \color{textwhite}3.5\% of cells $\Rightarrow$ 28\% synaptic output
  \vspace{6pt}}}
  \vspace{10pt}

  \colorbox{goldbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{accent}
    \textbf{Layer 5 recurrent:} \color{textwhite}4.7:1 ratio vs.\ feedforward
  \vspace{6pt}}}
  \vspace{10pt}

  \colorbox{goldbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{accent}
    \textbf{Inhibitory specificity:} \color{textwhite}6.2$\times$ higher than excitatory
  \vspace{6pt}}}
}

% ══ ROW B (row10-row15): Hub Neurons | Data Table | Layer Connectivity ══

\posterbox[goldcard, title={Hub Neuron Analysis}
]{name=hubs, column=1, between=row10 and row15}{
  \fontsize{34}{44}\selectfont

  \centering
  \colorbox{goldbox}{\parbox{0.94\linewidth}{\centering\vspace{10pt}
    {\fontsize{64}{76}\selectfont\bfseries\color{accent} 3.5\%}\\[6pt]
    {\fontsize{28}{34}\selectfont\color{textgray} of neurons}\\[8pt]
    {\fontsize{34}{42}\selectfont\color{textwhite} drive \textbf{\color{accent}28\%} of synaptic output}
  \vspace{10pt}}}

  \vspace{14pt}
  \raggedright
  \begin{itemize}[itemsep=12pt]
    \item Non-uniform influence distribution
    \item Focal lesion $\Rightarrow$ widespread effects
    \item Key for targeted stimulation design
  \end{itemize}
}

\posterbox[bluecard, title={Quantitative Summary}
]{name=table, column=2, between=row10 and row15}{
  \fontsize{30}{38}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.9}
  \begin{tabular}{p{0.50\linewidth}p{0.42\linewidth}}
    \rowcolor{electricblue!25}
    \textbf{\color{electricblue}Metric} & \textbf{\color{electricblue}Result} \\
    \rowcolor{bluebox}
    Neurons mapped & \textbf{{$\sim$}125,000} \\
    \rowcolor{cardbg}
    Synapses catalogued & \textbf{{$\sim$}54 million} \\
    \rowcolor{bluebox}
    Connectivity motifs & \textbf{37 types} \\
    \rowcolor{cardbg}
    Hub neuron fraction & \textbf{3.5\%} \\
    \rowcolor{bluebox}
    L5 recurrent ratio & \textbf{4.7:1} \\
    \rowcolor{cardbg}
    Inhibitory specificity & \textbf{6.2$\times$} \\
    \rowcolor{bluebox}
    Synapse detection & \textbf{94.2\%} \\
  \end{tabular}
}

\posterbox[tealcard, title={Layer-Specific Connectivity}
]{name=layers, column=3, between=row10 and row15}{
  \fontsize{34}{44}\selectfont

  \colorbox{tealbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{tealaccent}
    \textbf{Feedforward:} \color{textwhite}Layers 2/3 $\to$ Layer 4
  \vspace{6pt}}}
  \vspace{10pt}

  \colorbox{tealbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{tealaccent}
    \textbf{Recurrent enriched:} \color{textwhite}Layer 5 (4.7:1 ratio)
  \vspace{6pt}}}
  \vspace{10pt}

  \colorbox{tealbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{32}{40}\selectfont\color{tealaccent}
    \textbf{Inhibitory interneurons:} \color{textwhite}6.2$\times$ more specific than excitatory
  \vspace{6pt}}}
  \vspace{14pt}

  \begin{itemize}[itemsep=12pt]
    \item Challenges ``blanket inhibition'' model
    \item Suggests precise circuit computation
  \end{itemize}
}

% ══ ROW C (row15-row20): Implications | Future | Citation ══

\posterbox[highlightcard, title={Implications}
]{name=implications, column=1, between=row15 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item Modular motifs = finite circuit vocabulary
    \item Hub neurons explain focal lesion effects
    \item Informs brain-computer interface design
    \item Open-access dataset for community
  \end{itemize}
}

\posterbox[highlightcard, title={Future Directions}
]{name=future, column=2, between=row15 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{enumerate}[itemsep=14pt]
    \item Extend to additional brain regions
    \item Cross-species connectomic comparison
    \item Complete mammalian wiring diagram
  \end{enumerate}
  \vspace{10pt}
  \colorbox{secondary!20!primary}{\parbox{0.94\linewidth}{\vspace{6pt}\centering\fontsize{30}{38}\selectfont\color{secondary}
    \textbf{Open Access:} Dataset \& tools publicly released
  \vspace{6pt}}}
}

\posterbox[tealcard, title={Citation \& Resources}
]{name=refs, column=3, between=row15 and row20}{
  \fontsize{30}{40}\selectfont
  \textit{Nature} (2024)\\[6pt]
  DOI: 10.1038/s41586-024-07487-w\\[16pt]
  \colorbox{tealbox}{\parbox{0.94\linewidth}{\vspace{6pt}\fontsize{28}{36}\selectfont\color{textwhite}
    \textbf{Methods:} Serial-section EM, deep learning segmentation, graph-theoretic analysis, calcium imaging validation
  \vspace{6pt}}}
  \vspace{12pt}\\
  {\fontsize{28}{34}\selectfont\color{textmuted}
  Poster prepared for academic conference presentation}
}

\end{tcbposter}
\end{document}

